// --- WEBGL HERO ENGINE ---
const WebGLHero: React.FC = () => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const canvas = canvasRef.current;
        const container = containerRef.current;
        if (!canvas || !container) return;

        const gl = canvas.getContext('webgl');
        if (!gl) return;

        // Vertex Shader: Pass full screen quad
        const vsSource = `
            attribute vec2 position;
            void main() {
                gl_Position = vec4(position, 0.0, 1.0);
            }
        `;

        // Fragment Shader: Adapted from requested logic + Aspect Ratio Fix
        const fsSource = `
            precision highp float;
            uniform vec2 resolution;
            uniform float time;

            void main() {
                // Fix Aspect Ratio (Prevents Stretching)
                vec2 uv = (gl_FragCoord.xy * 2.0 - resolution) / min(resolution.x, resolution.y);

                // Ray origin and direction
                vec3 ro = vec3(0.0, 0.0, -time * 2.0); // Move forward
                vec3 rd = normalize(vec3(uv, 1.5));    // FOV 

                vec3 p = vec3(0.0);
                vec3 col = vec3(0.0);
                float z = 0.0;
                float d = 0.0;

                // Raymarching Loop (Adapted from prompt)
                for(float i=0.0; i<64.0; i++) {
                    p = ro + rd * z;

                    // The Requested Geometry Logic (Organic Tunnel)
                    // vec2(3.-abs(p.y)+dot(cos(p+.3*t),sin(.3*t-.6*p.yzx)) ...
                    float noise = dot(cos(p + 0.3 * time), sin(0.3 * time - 0.6 * p.yzx));
                    float tube = 3.0 - abs(p.y) + noise;
                    float detail = cos(p.x / 0.3 - p.z) * 0.3;

                    // Distance field
                    float geo = length(vec2(tube, detail));
                    d = max(0.0, 0.5 * geo - 0.1); 

                    // Accumulate Distance
                    z += max(d, 0.02);

                    // Accumulate Color (Glow)
                    // Infogito Palette: Teal/Cyan/Dark
                    float glow = 0.02 / (0.01 + d);
                    vec3 palette = 0.5 + 0.5 * cos(vec3(0.0, 0.33, 0.67) + i * 0.1 + p.z * 0.05);
                    vec3 brandTint = vec3(0.1, 0.8, 0.7); // Teal bias

                    col += glow * mix(palette, brandTint, 0.7) * 0.03;

                    if(z > 40.0) break;
                }

                // Tone mapping
                col = col / (1.0 + col);

                // Vignette
                col *= 1.0 - length(uv) * 0.4;

                gl_FragColor = vec4(col, 1.0);
            }
        `;

        const createShader = (type: number, source: string) => {
            const shader = gl.createShader(type);
            if (!shader) return null;
            gl.shaderSource(shader, source);
            gl.compileShader(shader);
            if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
                console.warn(gl.getShaderInfoLog(shader));
                gl.deleteShader(shader);
                return null;
            }
            return shader;
        };

        const vertexShader = createShader(gl.VERTEX_SHADER, vsSource);
        const fragmentShader = createShader(gl.FRAGMENT_SHADER, fsSource);
        if (!vertexShader || !fragmentShader) return;

        const program = gl.createProgram();
        if (!program) return;
        gl.attachShader(program, vertexShader);
        gl.attachShader(program, fragmentShader);
        gl.linkProgram(program);
        gl.useProgram(program);

        const positionBuffer = gl.createBuffer();
        gl.bindBuffer(gl.ARRAY_BUFFER, positionBuffer);
        // Full screen triangle strip
        gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1,-1, 1,-1, -1,1, 1,1]), gl.STATIC_DRAW);

        const positionLoc = gl.getAttribLocation(program, "position");
        gl.enableVertexAttribArray(positionLoc);
        gl.vertexAttribPointer(positionLoc, 2, gl.FLOAT, false, 0, 0);

        const timeLoc = gl.getUniformLocation(program, "time");
        const resLoc = gl.getUniformLocation(program, "resolution");

        let startTime = Date.now();
        let frameId: number;

        const render = () => {
            if (!canvas || !container) return;

            // Handle Resize
            const w = container.clientWidth;
            const h = container.clientHeight;

            if (canvas.width !== w || canvas.height !== h) {
                canvas.width = w;
                canvas.height = h;
                gl.viewport(0, 0, w, h);
            }

            gl.uniform2f(resLoc, w, h);
            gl.uniform1f(timeLoc, (Date.now() - startTime) * 0.001);

            gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);
            frameId = requestAnimationFrame(render);
        };

        render();

        return () => {
            cancelAnimationFrame(frameId);
            gl.deleteProgram(program);
        };
    }, []);

    return (
        <div ref={containerRef} className="absolute inset-0 w-full h-full bg-black">
            <canvas ref={canvasRef} className="block w-full h-full opacity-80 mix-blend-screen" />
        </div>
    );
};

