import React, { useEffect, useRef, useState } from 'react';
import { 
    Users, Handshake, ShieldCheck, Target, ArrowRight, 
    Truck, Zap, Activity, Factory, Briefcase, 
    Globe, Network, Layers, ChevronRight, ArrowUpRight, ScanLine,
    Database, Cpu, Lock, CheckCircle2, Terminal, ChevronDown
} from 'lucide-react';
import { useNavigation } from '../context/NavigationContext';

// --- WEBGL HERO ENGINE ---
const WebGLHero: React.FC = () => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const canvas = canvasRef.current;
        const container = containerRef.current;
        if (!canvas || !container) return;

        const gl = canvas.getContext('webgl');
        if (!gl) return;

        // Vertex Shader: Pass full screen quad
        const vsSource = `
            attribute vec2 position;
            void main() {
                gl_Position = vec4(position, 0.0, 1.0);
            }
        `;

        // Fragment Shader: Adapted Code Golf Logic
        // Original: 
        // vec3 p;
        // for(float i,z,f;i++<5e1;z+=f=.003+.1*abs(length(p)-5.),o.rgb+=(p/z+.8)/f)
        // for(p=z*(FC.rgb*2.-r.xyy)/r.y,p.z+=9.,f=1.;f++<7.;p+=sin(round(p.zxy/.1)*.1*f-t)/f);
        // o=tanh(o/2e3);
        const fsSource = `
            precision highp float;
            uniform vec2 resolution;
            uniform float time;

            // Tanh approximation for WebGL 1.0
            vec3 tanh_approx(vec3 x) {
                vec3 x2 = x*x;
                return clamp(x*(27.0 + x2)/(27.0+9.0*x2), 0.0, 1.0);
            }

            void main() {
                // Resolution and Time
                vec2 r = resolution;
                float t = time * 0.5; // Slowed down slightly for elegance

                // Aspect Corrected UV (Centered 0,0)
                vec2 uv = (gl_FragCoord.xy * 2.0 - r) / min(r.x, r.y);

                vec3 o = vec3(0.0); // Output color
                float z = 0.0;      // Distance accumulation

                // Outer Loop (Raymarch Steps) -> 50 iterations
                for(int i = 0; i < 50; i++) {

                    // Initialize p for this step (recreating the golf logic p=z*...)
                    // p is essentially a point along the ray at distance z
                    vec3 p = normalize(vec3(uv, 1.0)) * z; 
                    p.z += 9.0; // Camera offset

                    // Inner Loop (Fractal Distortion) -> 6 iterations
                    for(float f = 1.0; f < 7.0; f++) {
                        // round(x) = floor(x + 0.5)
                        vec3 q = p.zxy / 0.1;
                        vec3 rounded = floor(q + 0.5) * 0.1;

                        // p += sin(round(p.zxy/.1)*.1*f-t)/f
                        p += sin(rounded * f - t) / f;
                    }

                    // Distance Estimate
                    // f=.003+.1*abs(length(p)-5.)
                    float d = 0.003 + 0.1 * abs(length(p) - 5.0);

                    // Accumulate Distance
                    z += d;

                    // Accumulate Color
                    // Original: o.rgb += (p/z+.8)/f
                    // We modify this to inject the Teal Brand Color

                    // Calculate a structural tint based on position p
                    // This preserves the geometric "look" of the fractal
                    vec3 structTint = 0.5 + 0.5 * cos(p * 0.1 + t); 

                    // Brand Teal Base
                    vec3 brand = vec3(0.41, 0.71, 0.7); // #69B7B2

                    // Mix Brand with Structure
                    vec3 colorTerm = mix(brand, structTint, 0.3);

                    // Add brightness bias (the +.8 from original) but tinted
                    colorTerm += 0.2; 

                    // Accumulate with 1/d falloff (1/f in golf terms)
                    o += colorTerm / (d + 0.001);
                }

                // Final Tone Mapping
                // Original: o = tanh(o / 2e3)
                // We divide by a slightly smaller number to keep it brighter/sharper
                o = o / 1800.0;
                o = tanh_approx(o);

                // Slight Vignette
                o *= 1.0 - length(uv * 0.5);

                gl_FragColor = vec4(o, 1.0);
            }
        `;

        const createShader = (type: number, source: string) => {
            const shader = gl.createShader(type);
            if (!shader) return null;
            gl.shaderSource(shader, source);
            gl.compileShader(shader);
            if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
                console.warn(gl.getShaderInfoLog(shader));
                gl.deleteShader(shader);
                return null;
            }
            return shader;
        };

        const vertexShader = createShader(gl.VERTEX_SHADER, vsSource);
        const fragmentShader = createShader(gl.FRAGMENT_SHADER, fsSource);
        if (!vertexShader || !fragmentShader) return;

        const program = gl.createProgram();
        if (!program) return;
        gl.attachShader(program, vertexShader);
        gl.attachShader(program, fragmentShader);
        gl.linkProgram(program);
        gl.useProgram(program);

        const positionBuffer = gl.createBuffer();
        gl.bindBuffer(gl.ARRAY_BUFFER, positionBuffer);
        // Full screen triangle strip
        gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1,-1, 1,-1, -1,1, 1,1]), gl.STATIC_DRAW);

        const positionLoc = gl.getAttribLocation(program, "position");
        gl.enableVertexAttribArray(positionLoc);
        gl.vertexAttribPointer(positionLoc, 2, gl.FLOAT, false, 0, 0);

        const timeLoc = gl.getUniformLocation(program, "time");
        const resLoc = gl.getUniformLocation(program, "resolution");

        let startTime = Date.now();
        let frameId: number;

        const render = () => {
            if (!canvas || !container) return;

            // Handle Resize
            const w = container.clientWidth;
            const h = container.clientHeight;

            if (canvas.width !== w || canvas.height !== h) {
                canvas.width = w;
                canvas.height = h;
                gl.viewport(0, 0, w, h);
            }

            gl.uniform2f(resLoc, w, h);
            gl.uniform1f(timeLoc, (Date.now() - startTime) * 0.001);

            gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);
            frameId = requestAnimationFrame(render);
        };

        render();

        return () => {
            cancelAnimationFrame(frameId);
            gl.deleteProgram(program);
        };
    }, []);

    return (
        <div ref={containerRef} className="absolute inset-0 w-full h-full bg-black">
            <canvas ref={canvasRef} className="block w-full h-full opacity-90 mix-blend-screen" />
        </div>
    );
};

