// --- WEBGL HERO ENGINE (WebGL 2.0) ---
const WebGLHero: React.FC = () => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const canvas = canvasRef.current;
        const container = containerRef.current;
        if (!canvas || !container) return;

        // CRITICAL: Request WebGL 2 for 'tanh', 'round', and loop constructs
        const gl = canvas.getContext('webgl2');
        if (!gl) {
            console.error("WebGL 2 not supported");
            return;
        }

        // Vertex Shader: Standard Full-Screen Quad
        const vsSource = `#version 300 es
            in vec2 position;
            void main() {
                gl_Position = vec4(position, 0.0, 1.0);
            }
        `;

        // Fragment Shader: The Requested Fractal Logic + Brand Colors
        const fsSource = `#version 300 es
            precision highp float;
            uniform vec2 resolution;
            uniform float time;
            out vec4 fragColor;

            void main() {
                vec2 r = resolution;
                float t = time * 0.2; // Slow drift

                vec3 o = vec3(0.0);   // Color accumulator
                float z = 0.0;        // Ray distance

                // Normalized Pixel Coordinates (Aspect Corrected)
                vec2 uv = (gl_FragCoord.xy * 2.0 - r) / min(r.x, r.y);
                vec3 dir = normalize(vec3(uv, 1.0)); // Forward direction

                // --- GOLF LOGIC TRANSLATION ---
                // Original: for(float i,z,f;i++<5e1;z+=f=.003+.1*abs(length(p)-5.),o.rgb+=(p/z+.8)/f)
                //           for(p=z*(FC.rgb*2.-r.xyy)/r.y,p.z+=9.,f=1.;f++<7.;p+=sin(round(p.zxy/.1)*.1*f-t)/f);

                for(int i = 0; i < 50; i++) {
                    // 1. Position Initialization (Inner Loop Prep)
                    // p corresponds to current ray position distorted by z
                    vec3 p = z * dir; 
                    p.z += 9.0; // Camera offset

                    // 2. Fractal Distortion (Inner Loop)
                    for(float f = 1.0; f < 7.0; f++) {
                        // round(x) is floor(x + 0.5)
                        vec3 rounded = floor(p.zxy / 0.1 + 0.5) * 0.1;
                        p += sin(rounded * f - t) / f;
                    }

                    // 3. Distance Estimation
                    // f = .003 + .1 * abs(length(p) - 5.)
                    float den = 0.003 + 0.1 * abs(length(p) - 5.0);

                    // 4. March Forward
                    z += den;

                    // 5. Color Accumulation
                    // Original: o.rgb += (p/z + .8) / f

                    // INFOGITO BRAND MAPPING
                    // We map the spatial data 'p' to Teal/Cyan instead of full spectrum
                    float density = 1.0 / (den + 0.001); // Inverse distance for glow

                    // Core Brand Colors
                    vec3 teal = vec3(0.41, 0.71, 0.7);  // #69B7B2
                    vec3 cyan = vec3(0.02, 0.71, 0.83); // #06b6d4
                    vec3 deep = vec3(0.05, 0.1, 0.15);  // Dark backdrop

                    // Create structural gradient based on p
                    float structure = sin(p.x * 2.0) * cos(p.y * 2.0);
                    vec3 tint = mix(teal, cyan, structure * 0.5 + 0.5);

                    // Add brightness core based on iteration/depth
                    tint += vec3(0.2) / (z * 0.5 + 0.1);

                    // Accumulate
                    o += tint * density * 0.0015;
                }

                // 6. Tone Mapping
                // o = tanh(o / 2e3) -> adapted for our scale
                o = tanh(o); // WebGL2 Native

                // Vignette for cinematic look
                o *= 1.0 - dot(uv, uv) * 0.4;

                fragColor = vec4(o, 1.0);
            }
        `;

        // Shader Compilation
        const createShader = (type: number, source: string) => {
            const shader = gl.createShader(type);
            if (!shader) return null;
            gl.shaderSource(shader, source);
            gl.compileShader(shader);
            if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
                console.error("Shader Compile Error:", gl.getShaderInfoLog(shader));
                gl.deleteShader(shader);
                return null;
            }
            return shader;
        };

        const vertexShader = createShader(gl.VERTEX_SHADER, vsSource);
        const fragmentShader = createShader(gl.FRAGMENT_SHADER, fsSource);
        if (!vertexShader || !fragmentShader) return;

        const program = gl.createProgram();
        if (!program) return;
        gl.attachShader(program, vertexShader);
        gl.attachShader(program, fragmentShader);
        gl.linkProgram(program);
        gl.useProgram(program);

        // Quad Geometry
        const positionBuffer = gl.createBuffer();
        gl.bindBuffer(gl.ARRAY_BUFFER, positionBuffer);
        gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1,-1, 1,-1, -1,1, 1,1]), gl.STATIC_DRAW);

        const positionLoc = gl.getAttribLocation(program, "position");
        gl.enableVertexAttribArray(positionLoc);
        gl.vertexAttribPointer(positionLoc, 2, gl.FLOAT, false, 0, 0);

        const timeLoc = gl.getUniformLocation(program, "time");
        const resLoc = gl.getUniformLocation(program, "resolution");

        // Render Loop
        let startTime = Date.now();
        let frameId: number;

        const render = () => {
            if (!canvas || !container) return;

            // Robust resizing
            const w = container.clientWidth;
            const h = container.clientHeight;

            if (canvas.width !== w || canvas.height !== h) {
                canvas.width = w;
                canvas.height = h;
                gl.viewport(0, 0, w, h);
            }

            const time = (Date.now() - startTime) * 0.001;

            gl.uniform2f(resLoc, w, h);
            gl.uniform1f(timeLoc, time);

            gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);
            frameId = requestAnimationFrame(render);
        };

        render();

        return () => {
            cancelAnimationFrame(frameId);
            gl.deleteProgram(program);
        };
    }, []);

    return (
        <div ref={containerRef} className="absolute inset-0 w-full h-full bg-[#020202]">
            <canvas ref={canvasRef} className="block w-full h-full opacity-80" />
        </div>
    );
};

